#version 300 es
precision highp float;

uniform vec2 u_resolution; // resolution
uniform float u_doubling; // [-5, 5, 0.1]
uniform float u_amplitude;

uniform float u_rotation; // [0, 6.28, 0]
uniform float u_density;  // [10, 200, 30]
uniform vec4 u_color_1; // color [0,0,0,1]
uniform vec4 u_color_2; // color [1,1,1,1]

uniform sampler2D u_input_tex;
uniform float u_invert; // [0, 1, 1]


in vec2 vUv;
out vec4 fragColor;

const float PI = 3.1415926535897932384626433832795;

/*
angle is in radians
*/
vec2 rotate(vec2 uv, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c) * uv;
}

vec2 invRotate(vec2 uv, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, s, -s, c) * uv;
}

vec2 rotateCenter(vec2 uv, float angle) {
    return rotate(uv - vec2(.5), u_rotation) + vec2(.5);
}

void main() {
    vec2 uv = vec2(vUv.x, vUv.y);
    vec2 uvInRotatedSpace = invRotate(uv, u_rotation);
    vec2 targetPixInRot = vec2(floor(uvInRotatedSpace.x * u_density + 0.5)/u_density, uvInRotatedSpace.y);
    vec2 targetPixInRot2 = vec2(floor((uvInRotatedSpace.x) * u_density + 0.5)/u_density, uvInRotatedSpace.y  + u_doubling / 20.0);

    float distanceFromTargetInRot = smoothstep(0.0, 1.0, abs(targetPixInRot.x - uvInRotatedSpace.x) * 1.2) * 15.0 / (1.0 + u_amplitude * 5.0);
    float maxDist = 1.0 / u_density;

    vec2 targetInCart = invRotate(targetPixInRot, -u_rotation);
    vec2 targetInCart2 = invRotate(targetPixInRot2, -u_rotation);
    vec4 targetColor = (texture(u_input_tex, targetInCart) + texture(u_input_tex, targetInCart2)) * 0.5;

    float targetLum = pow(dot(targetColor.rgb, vec3(0.299, 0.587, 0.114)), 2.0);

    // 1.0 is solid; should be shaded. 0.0 should be white space
    float solidMask = clamp(targetLum, 0.0, 1.0) < distanceFromTargetInRot * u_density ? 1.0 : 0.0;


    if (u_invert > 0.5) {
        if (solidMask < 0.5) {
            fragColor = u_color_2;
        } else {
            fragColor = u_color_1;
        }
    } else {
        if (solidMask > 0.5) {
            fragColor = u_color_2;
        } else {
            fragColor = u_color_1;
        }
    }

}

#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_input_tex;
uniform float u_blur_dist; // [0, 1, 0.1]
uniform vec2 u_resolution; // resolution
uniform float u_angle; // [0, 10, 0]
uniform float u_blur_sample_count; // [2, 50, 5]
uniform float u_start_offset; // [0, 1, 0.5]


mat2 rotate2D(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(
        c, -s, 
        s,  c  
    );
}

void main() {
    vec2 aspect = vec2(
        u_resolution.x / u_resolution.y,
        1.0
    );

    vec2 uv = vUv * aspect;

    mat2 rot_mat = rotate2D(u_angle);
    mat2 inv_rot_mat = rotate2D(-u_angle);
    vec2 rotated_uv = rot_mat * uv;

    int count = int(floor(u_blur_sample_count));

    vec4 result = vec4(0.0);

    float offset_bias = u_blur_dist * u_start_offset;

    for (int i = 0; i < count; i++) {
        float offset = float(i) / float(count) * u_blur_dist - offset_bias;
        vec2 target_pos = rotated_uv + vec2(offset, 0.0);

        result += texture(
            u_input_tex,
            (inv_rot_mat * target_pos) / aspect
        );
    }

    fragColor = result / float(count);
}

#version 300 es
precision mediump float;

in vec2 vUv;
out vec4 fragColor;

uniform sampler2D u_texture_1;
uniform sampler2D u_texture_2;

void main() {
    fragColor = clamp(
        texture(u_texture_1, vUv) + texture(u_texture_2, vUv),
        vec4(0.),
        vec4(1.)
    );

}

